def board_for(kw):
    k = kw.lower()
    if "coach" in k or k.startswith("team"): return "coach"
    if "sports dad" in k: return "dad"
    if "gift" in k: return "gifts"
    if "stadium seat" in k: return "seat"
    if any(x in k for x in ["blanket", "cold ", "winter", "hockey"]): return "cold"
    if "wagon" in k: return "wagon"
    if any(x in k for x in ["travel", "tournament"]): return "travel"
    if any(x in k for x in ["game day", "football game"]): return "gameday"
    if any(x in k for x in ["summer", "outdoor"]): return "hot"
    return "bag"
